(() => { const vals = {"fullName":"Faith Wambui","email":"faith.wambui.98194@example.co.ke"};
  for (let [name, value] of Object.entries(vals)) {
    const el = document.querySelector('[name="' + name + '"]'); if (!el) throw new Error('no field ' + name)
    const proto = el.tagName === 'SELECT' ? HTMLSelectElement.prototype : el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype
    if (el.tagName === 'SELECT' && ![...el.options].some(o => o.value === value)) { const o = [...el.options].find(o => o.textContent.includes(value)); if (!o) throw new Error('no option ' + value); value = o.value }
    Object.getOwnPropertyDescriptor(proto, 'value').set.call(el, value)
    el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true }))
  } return true })()

